// NVRAM save file loading and saving.
//
// The save/load logic of 3DO.sv runs as is (save_load.svh, generated by prepare.py) with
// models of the HPS link (Main_MiSTer answering the sector requests of the core, through
// sys/hps_io.sv) and of the NVRAM port of the DDR3 controller (rtl/ddram.sv). For each test
// save file, the testbench loads it, compares the NVRAM with the expected one, saves it back
// and compares the file written with the expected one.
`timescale 1ns/1ps
module tb_nvram;

	reg clk_sys = 0, clk_mem = 0;
	always #10 clk_sys = ~clk_sys;	// 50 MHz
	always #5  clk_mem = ~clk_mem;	// 100 MHz, same PLL

	// Signals of 3DO.sv used by the save/load logic
	reg  [63:0] status = '0;
	reg         OSD_STATUS = 0;
	reg         SRAMW_N = 1;
	reg         save_download = 0, bios_download = 0, kanji_download = 0;
	reg         img_mounted = 0, img_readonly = 0;
	reg  [31:0] sd_lba = '0;
	reg         sd_rd = 0, sd_wr = 0;
	reg         sd_ack = 0;
	reg  [ 7:0] sd_buff_addr = '0;
	reg  [15:0] sd_buff_dout = '0;
	reg         sd_buff_wr = 0;
	wire [15:0] sd_buff_din;
	wire [15:0] ddr_nvram_do;
	wire        ddr_nvram_busy;
	wire [15:0] nvram_load_data;

	// NVRAM port of the ddram instance
	wire [14:1] tb_nvram_addr;
	wire [15:0] tb_nvram_din;
	wire        tb_nvram_wr, tb_nvram_rd;
	wire [15:0] tb_nvram_dout;
	wire        tb_nvram_busy;

`include "save_load.svh"

	// rtl/ddram.sv NVRAM port: a request is taken on the rising edge of nvram_wr or nvram_rd
	// (clk_mem) and the port stays busy until the DDR3 access is done. The NVRAM is kept as
	// the 16-bit words of the port (byte 2k in bits 15:8).
	reg  [15:0] nvram [0:16383];
	reg         old_wr = 0, old_rd = 0, wbusy = 0, rbusy = 0;
	reg  [14:1] waddr, raddr;
	reg  [15:0] wdata, rdata = '0;
	int         wcnt, rcnt;
	int         nvram_writes = 0;
	always @(posedge clk_mem) begin
		old_wr <= tb_nvram_wr;
		old_rd <= tb_nvram_rd;
		if (tb_nvram_wr && !old_wr) begin
			waddr <= tb_nvram_addr;
			wdata <= tb_nvram_din;
			wbusy <= 1;
			wcnt <= $urandom_range(1, 12);
		end
		else if (wbusy) begin
			if (wcnt == 0) begin
				nvram[waddr] <= wdata;
				nvram_writes <= nvram_writes + 1;
				wbusy <= 0;
			end
			else wcnt <= wcnt - 1;
		end
		if (tb_nvram_rd && !old_rd) begin
			raddr <= tb_nvram_addr;
			rbusy <= 1;
			rcnt <= $urandom_range(1, 12);
		end
		else if (rbusy) begin
			if (rcnt == 0) begin
				rdata <= nvram[raddr];
				rbusy <= 0;
			end
			else rcnt <= rcnt - 1;
		end
	end
	assign tb_nvram_busy = wbusy | rbusy;
	assign tb_nvram_dout = rdata;

	// Main_MiSTer through sys/hps_io.sv: a sector request (sd_rd or sd_wr) is answered after a
	// while, sd_ack staying high while the 256 words of the sector go through sd_buff_*.
	// The testbench drives its signals on the falling edge of clk_sys.
	reg  [15:0] sd_file  [0:16383];	// save file read by the core (byte 2k in bits 7:0)
	reg  [15:0] sd_saved [0:16383];	// save file written by the core
	int         saved_words = 0;
	bit         sd_read;
	int         sd_sector;
	initial forever begin
		@(negedge clk_sys);
		if (sd_rd || sd_wr) begin
			sd_read = sd_rd;
			sd_sector = sd_lba;
			if (sd_sector > 63) begin
				$display("TB FAIL sector %0d requested", sd_sector);
				$finish;
			end
			repeat ($urandom_range(2, 40)) @(negedge clk_sys);
			sd_ack = 1;
			sd_buff_addr = 0;
			for (int i = 0; i < 256; i++) begin
				repeat ($urandom_range(1, 6)) @(negedge clk_sys);
				sd_buff_addr = i[7:0];
				if (sd_read) begin
					sd_buff_dout = sd_file[sd_sector*256 + i];
					sd_buff_wr = 1;
					@(negedge clk_sys) sd_buff_wr = 0;
				end
				else begin
					repeat (2) @(negedge clk_sys);
					sd_saved[sd_sector*256 + i] = sd_buff_din;
					saved_words++;
				end
			end
			repeat ($urandom_range(1, 6)) @(negedge clk_sys);
			sd_ack = 0;
		end
	end

	reg  [15:0] exp_nvram [0:16383];
	reg  [15:0] exp_saved [0:16383];
	string      dir;
	int         errors = 0;

	// Main_MiSTer p3do_mount_save(): the save file is mounted in a download window
	task automatic mount_save();
		@(negedge clk_sys) save_download = 1;
		repeat (8) @(negedge clk_sys);
		img_mounted = 1;
		@(negedge clk_sys) img_mounted = 0;
		repeat (8) @(negedge clk_sys);
		save_download = 0;
	endtask

	// OSD option (status bit)
	task automatic osd(input int n);
		@(negedge clk_sys) status[n] = 1;
		repeat (4) @(negedge clk_sys);
		status[n] = 0;
	endtask

	task automatic wait_transfer(input string what);
		int t = 0;
		while (!bk_state) begin
			@(negedge clk_sys);
			t = t + 1;
			if (t > 1000) begin $display("TB FAIL %s: no transfer", what); $finish; end
		end
		while (bk_state) begin
			@(negedge clk_sys);
			t = t + 1;
			if (t > 2000000) begin $display("TB FAIL %s: transfer not finished", what); $finish; end
		end
		repeat (4) @(negedge clk_sys);
	endtask

	// Load a test save file (mounted by Main_MiSTer or loaded from the OSD), check the NVRAM,
	// save it back from the OSD and check the file written
	task automatic scenario(input string name, input bit from_osd, input bit has_label);
		int writes, words, bad_nvram = 0, bad_saved = 0, first_nvram = -1, first_saved = -1;
		$readmemh({dir, "/", name, ".sd.memh"}, sd_file);
		$readmemh({dir, "/", name, ".nv.memh"}, exp_nvram);
		$readmemh({dir, "/", name, ".sav.memh"}, exp_saved);

		writes = nvram_writes;
		if (from_osd) osd(12);	// Load Backup RAM
		else mount_save();
		wait_transfer({name, " load"});
		writes = nvram_writes - writes;
		for (int k = 0; k < 16384; k++) if (nvram[k] !== exp_nvram[k]) begin
			if (first_nvram < 0) first_nvram = k;
			bad_nvram++;
		end

		words = saved_words;
		osd(13);	// Save Backup RAM
		wait_transfer({name, " save"});
		words = saved_words - words;
		for (int k = 0; k < 16384; k++) if (sd_saved[k] !== exp_saved[k]) begin
			if (first_saved < 0) first_saved = k;
			bad_saved++;
		end

		if (writes != 16384 || words != 16384 || bad_nvram || bad_saved) begin
			errors++;
			$display("TB FAIL %s: %0d NVRAM words written, %0d differ%s; %0d file words saved, %0d differ%s", name,
				writes, bad_nvram, first_nvram < 0 ? "" : $sformatf(" (word %0h = %04h, expected %04h)", first_nvram, nvram[first_nvram], exp_nvram[first_nvram]),
				words, bad_saved, first_saved < 0 ? "" : $sformatf(" (word %0h = %04h, expected %04h)", first_saved, sd_saved[first_saved], exp_saved[first_saved]));
		end
		else if (has_label) $display("TB OK   %-10s volume loaded unchanged", name);
		else $display("TB OK   %-10s no volume label: blank NVRAM loaded", name);
	endtask

	initial begin
		if (!$value$plusargs("IMG=%s", dir)) dir = "img";
		repeat (10) @(negedge clk_sys);
`include "scenarios.svh"
		if (errors) $display("TB FAIL %0d save file(s)", errors);
		else $display("TB PASS");
		$finish;
	end

endmodule
